'use strict';

// Preserve links generated by the original browser-only version.
if (location.hash.length > 1 && typeof LZString !== 'undefined') {
  const decoded = LZString.decompressFromEncodedURIComponent(location.hash.slice(1));
  try {
    const target = new URL(decoded);
    if (['http:', 'https:'].includes(target.protocol) && !target.username && !target.password) {
      location.replace(target.href);
    } else {
      document.getElementById('error').textContent = 'This link is not valid.';
    }
  } catch {
    document.getElementById('error').textContent = 'This link is not valid.';
  }
}
